// Läsläge (F9b, k-028) – luminusloom.net
// AI-skapat (B-051). Generated by AI, Directed by MS.
// Slår på och av större text och kortare rader. Valet sparas bara i besökarens webbläsare
// (localStorage, nyckeln "laslage"), i samma format som Dag/natt. Inget skickas till servern, inget mäts.
(function () {
  var NYCKEL = 'laslage';
  var rot = document.documentElement;
  function las() { try { return JSON.parse(localStorage.getItem(NYCKEL)) === 'pa'; } catch (e) { return false; } }
  function spara(pa) { try { if (pa) localStorage.setItem(NYCKEL, JSON.stringify('pa')); else localStorage.removeItem(NYCKEL); } catch (e) { /* utan lagring gäller valet tills sidan laddas om */ } }
  function satt(pa) {
    if (pa) rot.setAttribute('data-laslage', 'pa'); else rot.removeAttribute('data-laslage');
    var knapp = document.getElementById('lasBtn');
    if (knapp) knapp.setAttribute('aria-pressed', pa ? 'true' : 'false');
  }
  // Körs i sidhuvudet, så att sidan inte hoppar mellan storlekarna när den laddas.
  satt(las());
  function koppla() {
    var knapp = document.getElementById('lasBtn');
    if (!knapp) return;
    satt(rot.getAttribute('data-laslage') === 'pa');
    knapp.addEventListener('click', function () {
      var pa = rot.getAttribute('data-laslage') !== 'pa';
      satt(pa);
      spara(pa);
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', koppla); else koppla();
})();
